// Auth Guard — deployed by HomeBot; validates X-HOMEBOT-Auth.
let secret = "";
if (!secret) secret = process.env.HOMEBOT_WEBHOOK_SECRET;
const hdrs = $input.first()?.json?.headers || {};
const incoming = hdrs['x-homebot-auth'] || hdrs['X-HOMEBOT-Auth'] || '';
if (!secret) {
  throw new Error('Unauthorized: this workflow has no HomeBot secret. Deploy it from HomeBot instead of importing it by hand.');
}
if (incoming !== secret) {
  throw new Error('Unauthorized: invalid or missing X-HOMEBOT-Auth header');
}
return $input.all();

const input = $input.item.json;
const params = input.tool_call?.parameters || input.body?.tool_call?.parameters || input;
const action = params.action;

const actionMap = {
  'extract_archive': 'extract',
  'create_archive': 'create',
  'list_archive': 'list'
};

const mappedAction = actionMap[action] || action;

return {
  json: {
    action: mappedAction,
    params: params,
    original_request: input
  }
};

const stdout = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';

let validationResult;
try {
  validationResult = JSON.parse(stdout);
} catch (e) {
  validationResult = {
    success: false,
    error: 'Failed to parse safety validation output',
    raw_output: stdout
  };
}

if (!validationResult.success) {
  return {
    json: {
      status: 'validation_failed',
      error: validationResult.error || 'Safety validation failed',
      validation: validationResult
    }
  };
}

return {
  json: {
    ...$input.item.json,
    validation: validationResult
  }
};

const stdout = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';

let scriptResult;
try {
  scriptResult = JSON.parse(stdout);
} catch (e) {
  scriptResult = {
    success: false,
    error: 'Failed to parse ArchiveOps output',
    raw_output: stdout
  };
}

return {
  json: {
    status: scriptResult.success ? 'success' : 'failure',
    timestamp: scriptResult.timestamp || new Date().toISOString(),
    operation: 'ArchiveOps',
    action: scriptResult.action || $input.item.json.action,
    data: scriptResult.data || null,
    error: scriptResult.error || null,
    validation: $input.item.json.validation
  }
};
